// test_main_tracing.rs - Test suite for main routine dependency tracing
// Generated by step4_bootstrap - Main Routine Tracing

use split_decls_genesis::{
    mkmain_trees, mkfull_main_analysis, find_all_main_routines, 
    build_reaching_tree, get_rustc_dependencies, MainRoutine, DependencyTree
};

fn main() -> anyhow::Result<()> {
    println!("🧬 Testing main routine dependency tracing...");
    
    // Run full main analysis
    let trees = mkfull_main_analysis!();
    
    println!("\n📊 DETAILED ANALYSIS:");
    
    let mut total_main_routines = 0;
    let mut total_functions_traced = 0;
    let mut total_calls_traced = 0;
    
    for tree in &trees {
        total_main_routines += 1;
        total_functions_traced += tree.total_functions;
        total_calls_traced += tree.reaching_tree.values().map(|v| v.len()).sum::<usize>();
        
        println!("\n🎯 MAIN: {} ({})", tree.main_routine.crate_name, tree.main_routine.name);
        println!("  📍 Location: {}", tree.main_routine.file_path);
        println!("  🔧 Functions in dependency tree: {}", tree.total_functions);
        println!("  📞 Total function calls traced: {}", 
                 tree.reaching_tree.values().map(|v| v.len()).sum::<usize>());
        
        // Show most connected functions
        let mut call_counts: Vec<_> = tree.reaching_tree.iter()
            .map(|(func, calls)| (func, calls.len()))
            .collect();
        call_counts.sort_by(|a, b| b.1.cmp(&a.1));
        
        println!("  🌟 Most connected functions:");
        for (func, count) in call_counts.iter().take(5) {
            println!("    {} → {} calls", func, count);
        }
    }
    
    println!("\n🎯 SUMMARY:");
    println!("  🏗️  Total main routines found: {}", total_main_routines);
    println!("  🔧 Total functions traced: {}", total_functions_traced);
    println!("  📞 Total calls traced: {}", total_calls_traced);
    
    if total_main_routines > 0 {
        println!("  📈 Average functions per main: {}", 
                 total_functions_traced / total_main_routines);
        println!("  📈 Average calls per main: {}", 
                 total_calls_traced / total_main_routines);
    }
    
    // Show reaching tree structure for first main
    if let Some(first_tree) = trees.first() {
        println!("\n🌳 SAMPLE REACHING TREE ({})", first_tree.main_routine.crate_name);
        println!("  📊 Tree structure:");
        
        let mut depth_map = std::collections::HashMap::new();
        trace_depth(&first_tree.reaching_tree, "main", 0, &mut depth_map);
        
        let mut depths: Vec<_> = depth_map.iter().collect();
        depths.sort_by_key(|(_, depth)| **depth);
        
        for (func, depth) in depths.iter().take(10) {
            let indent = "  ".repeat(**depth as usize);
            println!("  {}└─ {}", indent, func);
        }
    }
    
    println!("\n🎉 Main routine tracing complete!");
    Ok(())
}

fn trace_depth(
    tree: &std::collections::HashMap<String, Vec<String>>, 
    func: &str, 
    depth: u32, 
    depth_map: &mut std::collections::HashMap<String, u32>
) {
    if depth > 5 { return; } // Prevent infinite recursion
    
    depth_map.entry(func.to_string()).or_insert(depth);
    
    if let Some(calls) = tree.get(func) {
        for call in calls.iter().take(3) { // Limit to prevent explosion
            trace_depth(tree, call, depth + 1, depth_map);
        }
    }
}
